def test_wcag_contrast_ratios(root_properties: Dict[str, str]) -> None:
    """All foreground/background pairs must meet WCAG AA contrast."""
    failures: List[str] = []
    for fg_prop, bg_prop in CONTRAST_PAIRS:
        fg = root_properties.get(fg_prop, "")
        bg = root_properties.get(bg_prop, "")
        if not fg or not bg:
            failures.append(f"{fg_prop} or {bg_prop} not defined")
            continue
        try:
            ratio = _calculate_contrast_ratio(fg, bg)
            if ratio < MIN_CONTRAST_NORMAL:
                failures.append(
                    f"{fg_prop} vs {bg_prop}: ratio {ratio:.2f} < {MIN_CONTRAST_NORMAL}"
                )
        except ValueError as e:
            failures.append(f"{fg_prop} vs {bg_prop}: {e}")
    assert not failures, f"WCAG contrast failures:\n" + "\n".join(failures)


