def _is_valid_color(value: str) -> bool:
    """Check if a string is a valid CSS color."""
    value = value.strip().lower()
    # Hex colors
    if re.match(r"^#[0-9a-f]{6}$", value) or re.match(r"^#[0-9a-f]{3}$", value):
        return True
    # rgb()/rgba()
    if re.match(r"^rgba?\([^)]+\)$", value):
        return True
    # hsl()/hsla()
    if re.match(r"^hsla?\([^)]+\)$", value):
        return True
    # Named colors (common set)
    named_colors = {
        "black", "white", "red", "green", "blue", "yellow", "orange",
        "purple", "pink", "gray", "grey", "transparent", "currentcolor",
    }
    if value in named_colors:
        return True
    # Try colour library
    try:
        Color(value)
        return True
    except Exception:
        return False


def _calculate_contrast_ratio(fg: str, bg: str) -> float:
    """
    Calculate WCAG contrast ratio between two colors.
    Returns ratio as float (1.0 to 21.0).
    """
    try:
        fg_color = Color(fg)
        bg_color = Color(bg)
    except Exception as e:
        raise ValueError(f"Invalid color: {e}")

    # Convert to RGB (0-1 range)
    fg_rgb = _hex_to_rgb(fg_color.hex_l)
    bg_rgb = _hex_to_rgb(bg_color.hex_l)

    # Calculate relative luminance
    fg_luminance = _relative_luminance(fg_rgb)
    bg_luminance = _relative_luminance(bg_rgb)

    # Ensure lighter color is first
    lighter = max(fg_luminance, bg_luminance)
    darker = min(fg_luminance, bg_luminance)

    return (lighter + 0.05) / (darker + 0.05)


def _hex_to_rgb(hex_str: str) -> Tuple[float, float, float]:
    """Convert hex color string to RGB tuple (0-1 range)."""
    hex_str = hex_str.lstrip("#")
    if len(hex_str) == 3:
        hex_str = "".join(c * 2 for c in hex_str)
    r = int(hex_str[0:2], 16) / 255.0
    g = int(hex_str[2:4], 16) / 255.0
    b = int(hex_str[4:6], 16) / 255.0
    return (r, g, b)


def _relative_luminance(rgb: Tuple[float, float, float]) -> float:
    """Calculate WCAG relative luminance."""
    def linearize(channel: float) -> float:
        if channel <= 0.03928:
            return channel / 12.92
        return ((channel + 0.055) / 1.055) ** 2.4

    r, g, b = rgb
    return 0.2126 * linearize(r) + 0.7152 * linearize(g) + 0.0722 * linearize(b)


